<?php

namespace App\Console\Commands;

use App\Models\CmsPage;
use App\Models\SuccessStory;
use Illuminate\Console\Command;
use Illuminate\Support\Carbon;

/**
 * `php artisan matrimony:sitemap` — write public/sitemap.xml.
 *
 * docs/05-website-guide.md §6: "generated by a scheduled command from CMS
 * pages, plans and success stories — **never from profiles**". That exclusion
 * is the important half and is not a performance decision. A profile is
 * visible to a signed-out visitor only when its owner set `profile_visibility`
 * to `all`; listing profiles here would either publish the ones who did not
 * choose that, or publish a set that silently changes every time somebody
 * edits their privacy settings — leaving a crawler holding URLs that now 404.
 * `/browse` is in the sitemap and is the one public door onto profiles; the
 * profiles themselves are not.
 *
 * Written to a **file** rather than served from a route on purpose: nginx
 * serves it without ever entering PHP, which is what you want for a URL that
 * bots fetch on their own schedule. The cost is that it can go stale, which is
 * what the daily schedule entry in routes/console.php is for — and why the
 * deploy script runs it too, so a release that adds a page does not wait until
 * the next morning to advertise it.
 *
 * No `<priority>`: Google has said for years that it ignores the field, and a
 * hand-assigned number that nothing reads is a number that will drift out of
 * date and mislead the next person who reads this file.
 */
class GenerateSitemap extends Command
{
    protected $signature = 'matrimony:sitemap';

    protected $description = 'Write public/sitemap.xml from CMS pages, plans and success stories';

    public function handle(): int
    {
        $urls = [
            ...$this->staticRoutes(),
            ...$this->cmsPages(),
            ...$this->successStories(),
        ];

        $path = public_path('sitemap.xml');

        file_put_contents($path, $this->render($urls));

        $this->info(count($urls).' URLs written to '.$path);

        $this->pointRobotsAtSitemap();

        return self::SUCCESS;
    }

    /**
     * Rewrite the `Sitemap:` line in public/robots.txt with an absolute URL.
     *
     * The directive is required to be absolute — a relative path is ignored by
     * every major crawler — and public/robots.txt is a static file with no
     * APP_URL to interpolate, so it ships with a relative placeholder and this
     * corrects it. Doing it here rather than in a second command means staging
     * and production need one checked-in robots.txt between them instead of a
     * per-environment copy that will drift.
     *
     * Every existing Sitemap line is dropped before the new one is appended, so
     * running this a hundred times leaves exactly one.
     */
    protected function pointRobotsAtSitemap(): void
    {
        $path = public_path('robots.txt');

        if (! is_file($path)) {
            $this->warn('No public/robots.txt — skipping the Sitemap directive.');

            return;
        }

        $lines = array_filter(
            explode("\n", rtrim((string) file_get_contents($path), "\n")),
            fn (string $line) => ! str_starts_with(strtolower(trim($line)), 'sitemap:'),
        );

        $lines[] = 'Sitemap: '.url('/sitemap.xml');

        file_put_contents($path, implode("\n", $lines)."\n");
    }

    // --- Sources -----------------------------------------------------------

    /**
     * The routes that always exist, with no row behind them.
     *
     * `/plans` is here rather than one entry per plan: a membership plan has no
     * URL of its own — the plans page renders all of them — so emitting one
     * URL per plan would be three copies of one page competing with each other
     * in the index.
     *
     * @return array<int, array{loc: string, lastmod: string|null, changefreq: string}>
     */
    protected function staticRoutes(): array
    {
        return [
            ['loc' => route('home'), 'lastmod' => null, 'changefreq' => 'daily'],
            ['loc' => route('browse'), 'lastmod' => null, 'changefreq' => 'daily'],
            ['loc' => route('membership.plans'), 'lastmod' => null, 'changefreq' => 'weekly'],
            ['loc' => route('page.faq'), 'lastmod' => null, 'changefreq' => 'monthly'],
            ['loc' => route('page.stories'), 'lastmod' => null, 'changefreq' => 'weekly'],
            ['loc' => route('page.contact'), 'lastmod' => null, 'changefreq' => 'yearly'],
        ];
    }

    /**
     * Published pages only — the same scope Web\PageController reads through.
     * A draft terms page must not be advertised to a crawler that would then
     * fetch it and get the 404 the controller correctly returns.
     *
     * `contact-us` is excluded: its content is rendered inside `/contact`,
     * which is already listed above, and the bare `/contact-us` slug would be
     * a second URL for the same words.
     */
    protected function cmsPages(): array
    {
        return CmsPage::published()
            ->where('slug', '!=', 'contact-us')
            ->get(['slug', 'updated_at'])
            ->map(fn (CmsPage $page) => [
                'loc' => route('page.show', $page->slug),
                'lastmod' => $page->updated_at?->toAtomString(),
                'changefreq' => 'monthly',
            ])
            ->all();
    }

    /**
     * The success-stories index carries a `lastmod` derived from the newest
     * published story, because that is what actually changes — the individual
     * stories have no page of their own to link to.
     */
    protected function successStories(): array
    {
        $latest = SuccessStory::published()->max('updated_at');

        if (! $latest) {
            return [];
        }

        return [[
            'loc' => route('page.stories'),
            'lastmod' => Carbon::parse($latest)->toAtomString(),

            // Deliberately duplicates the entry in staticRoutes() only in
            // `loc`; render() keeps the last write for a given URL, so this is
            // the same page gaining a real lastmod rather than a second URL.
            'changefreq' => 'weekly',
        ]];
    }

    // --- Rendering ---------------------------------------------------------

    /**
     * Hand-built XML rather than a package: this is forty lines of a format
     * that has not changed since 2005, and adding a Composer dependency to a
     * deploy for it is a worse trade than owning the string.
     *
     * Keyed by `loc` before rendering so a URL contributed by two sources
     * appears once, with the later source's metadata winning.
     */
    protected function render(array $urls): string
    {
        $unique = [];

        foreach ($urls as $url) {
            $unique[$url['loc']] = $url;
        }

        $xml = ['<?xml version="1.0" encoding="UTF-8"?>'];
        $xml[] = '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';

        foreach ($unique as $url) {
            $xml[] = '  <url>';
            // ENT_QUOTES|ENT_SUBSTITUTE alongside ENT_XML1: the flags argument
            // REPLACES htmlspecialchars' default set rather than adding to it,
            // so ENT_XML1 on its own silently turns off quote escaping and the
            // invalid-sequence substitution the default has.
            $xml[] = '    <loc>'.htmlspecialchars($url['loc'], ENT_QUOTES | ENT_SUBSTITUTE | ENT_XML1).'</loc>';

            if ($url['lastmod']) {
                $xml[] = '    <lastmod>'.$url['lastmod'].'</lastmod>';
            }

            $xml[] = '    <changefreq>'.$url['changefreq'].'</changefreq>';
            $xml[] = '  </url>';
        }

        $xml[] = '</urlset>';

        return implode("\n", $xml)."\n";
    }
}
